import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import ts from 'typescript';
const helper=fs.readFileSync('src/lib/publicationTitleEdit.ts','utf8');
const compiled=ts.transpileModule(helper,{compilerOptions:{target:ts.ScriptTarget.ES2020,module:ts.ModuleKind.CommonJS}}).outputText;
const sandbox={exports:{},require:()=>({getResolvedGenre:()=> 'Indie Pop'})};
vm.runInNewContext(compiled,sandbox);
const {buildPublicationTitlePatch:patch,readPublicationTitleDraft:read,isPublicationTitleSource:owns,assertPublicationTitleNotSuperseded:guard}=sandbox.exports;
const row={id:'one',uid:'owner',title:"[Indie Pop] '먼 길을 돌아온 밤'",genre:'indie_pop',displayGenre:'Indie Pop',likeCount:12};
assert.equal(read(row).korean,'먼 길을 돌아온 밤');
assert.equal(patch(row,null),null);
assert.equal(patch(row,read(row)),null);
assert.equal(patch(row,{korean:'새 제목',english:''}).title,'새 제목');
assert.equal(patch(row,{korean:'새 제목',english:'New Title'}).title,'새 제목 | New Title');
assert.deepEqual(Object.keys(patch(row,{korean:'새 제목',english:''})).sort(),['englishTitle','koreanTitle','title']);
assert.throws(()=>patch(row,{korean:' ',english:''}));
assert.throws(()=>patch(row,{korean:'a'.repeat(301),english:''}));
assert.equal(owns(row,'owner','one'),true);
assert.equal(owns(row,'other','one'),false);
assert.equal(owns(row,'owner','two'),false);
assert.equal(owns({...row,sharedReadOnly:true},'owner','one'),false);
assert.equal(owns({...row,hidden:true},'owner','one'),false);
assert.throws(()=>guard(row,{...row,title:'다른 수정'},{korean:'새 제목',english:''}));
guard(row,{...row,title:'새 제목'},{korean:'새 제목',english:''});
const f=fs.readFileSync('src/pages/FavoritesPage.tsx','utf8');
const e=fs.readFileSync('src/pages/ExplorePage.tsx','utf8');
const m=fs.readFileSync('src/components/explore/ExplorePublicationSettingsModal.tsx','utf8');
const c=fs.readFileSync('src/components/explore/PublicationTitleEditor.tsx','utf8');
const app=fs.readFileSync('src/App.tsx','utf8');
assert.match(f,/length === 1 && <PublicationSingleCover/);
assert.match(f,/length > 1 && \(/);
assert.match(m,/trackChoices.length === 1 && <PublicationSingleCover/);
assert.match(m,/trackChoices.length > 1 && \(/);
const single=c.slice(c.indexOf('export function PublicationSingleCover'));
assert.doesNotMatch(single,/<button|onClick|aria-pressed/);
assert.match(c,/text-xs font-semibold leading-tight text-white\/45">\[\{genre\}\]<\/p>/);
assert.match(c,/text-base font-bold leading-snug text-white\/90">\{displayed/);
assert.match(single,/aspect-\[32\/9\]/);
assert.match(single,/\{title \|\| '수노 곡 1'\}/);
assert.match(single,/available \? '공개 가능' : '연결 확인 필요'/);
assert.match(m,/title=\{formatExploreDisplayTitle\(trackChoices\[0\]\.title\)[^\n]*available=\{trackChoices\[0\]\.available !== false\}/);
assert.match(f,/title=\{String\(getFavoriteSunoLinks\(explorePublicationDialog\.song\)\[0\]\?\.title[^\n]*\n\s*available=\{isConnectedFavoriteSunoLink\(getFavoriteSunoLinks\(explorePublicationDialog\.song\)\[0\]\)\}/);
assert.match(f,/await updateFavorite\(sourceId,updates\)[\s\S]*?await refreshExploreMusicNotePublicationContent428/);
assert.match(e,/await updateFavorite\(sourceId,updates,undefined,latest\)[\s\S]*?await refreshExploreMusicNotePublicationContent428/);
assert.match(app,/<ExploreShellLazy\b[^>]*\bupdateFavorite=\{updateFavorite\}/);
for(const s of [f,e,m,c])assert.equal(ts.createSourceFile('file.tsx',s,ts.ScriptTarget.Latest,true,ts.ScriptKind.TSX).parseDiagnostics.length,0);
console.log('PUBLICATION_TITLE_DRAFT_IDENTITY_AND_SINGLE_NONSELECTABLE_COVER=PASS');
